/// Read a stored connection list and build the effective graph.
///
/// `ports_for` returns the ports of one instance, or `Error(Nil)` when the
/// instance is not known. The function sorts the list by connection ID, drops
/// any ID that repeats, checks each remaining connection, and keeps only the
/// connections that pass and that do not make a cycle.
pub fn effective(
  stored: List(Connection),
  ports_for: fn(String) -> Result(List(port.Descriptor), Nil),
) -> EffectiveGraph {
  let sorted =
    list.sort(stored, fn(left, right) {
      canonical_json.compare(left.id, right.id)
    })
  let duplicates = duplicated_ids(sorted)
  let final =
    list.fold(sorted, new_state(), fn(state, connection) {
      step(state, connection, duplicates, ports_for)
    })
  EffectiveGraph(
    connections: list.reverse(final.accepted),
    errors: list.reverse(final.errors),
  )
}

fn ports(instance_id: String) -> Result(List(port.Descriptor), Nil) {
  case instance_id {
    "tasks" -> Ok([port.Descriptor("completed", port.OutputPort, "task@1")])
    "activity" ->
      Ok([
        port.Descriptor(
          "append",
          port.InputPort(
            port.CollaborativeInput(capabilities: ["sequence:insert"]),
          ),
          "task@1",
        ),
      ])
    "notes" ->
      Ok([port.Descriptor("focus", port.InputPort(port.LocalInput), "task@1")])
    _ -> Error(Nil)
  }
}

fn graph() -> port_graph.EffectiveGraph {
  port_graph.effective(
    [
      port_graph.connection(
        "activity",
        port_graph.PortRef("tasks", "completed"),
        port_graph.PortRef("activity", "append"),
      ),
      port_graph.connection(
        "notes",
        port_graph.PortRef("tasks", "completed"),
        port_graph.PortRef("notes", "focus"),
      ),
    ],
    ports,
  )
}

/// Plan the deliveries for one payload at one output port.
///
/// `graph` supplies the effective connections in graph order. `ports_for`
/// re-reads the current port descriptors for one instance, so the plan
/// catches a port that a host catalog change removed or changed since the
/// graph was built. The plan compares the current schema ID of the source
/// port against the current schema ID of each target port, and it reports
/// `SchemaChanged` for a target that no longer matches. Returns an empty
/// plan without reading the graph when `origin` is `ReplicatedChange`.
pub fn plan(
  trace_id trace_id: String,
  origin origin: Origin,
  source source: port_graph.PortRef,
  payload payload: Json,
  graph graph: port_graph.EffectiveGraph,
  ports_for ports_for: fn(String) -> Result(List(port.Descriptor), Nil),
) -> Plan {
  case origin {
    ReplicatedChange -> Plan(deliveries: [], errors: [])
    LocalIntent ->
      plan_local_intent(Trace(trace_id), source, payload, graph, ports_for)
  }
}

