/// Link an output port to an input port with the same payload type.
///
/// Returns `Error(SchemaMismatch(..))` when the two ports name different
/// schema IDs, even though the compiler already checked the payload type.
pub fn connect(
  output: Output(payload),
  input: Input(payload),
) -> Result(ConnectionTemplate, PortError) {
  case output.schema_id == input.schema_id {
    True ->
      Ok(ConnectionTemplate(
        source_port: output.id,
        target_port: input.id,
        schema_id: output.schema_id,
      ))
    False ->
      Error(SchemaMismatch(source: output.schema_id, target: input.schema_id))
  }
}

/// The port metadata a descriptor lists.
pub fn ports(
  descriptor: Descriptor(context, running),
) -> List(port.Descriptor) {
  descriptor.ports
}

/// Deliver an encoded payload to one typed input handler.
pub fn deliver(
  descriptor: Descriptor(context, running),
  running: running,
  input_id: String,
  payload: Json,
) -> Result(#(running, List(OutputEvent)), ComponentError) {
  case matching_input(descriptor, input_id) {
    None ->
      Error(InputUnavailable(descriptor.kind, descriptor.version, input_id))
    Some(handler) ->
      handler.deliver(running, payload)
      |> result.map_error(fn(reason) {
        case reason {
          HandlerInvalidPayload(reason) ->
            InvalidInputPayload(
              descriptor.kind,
              descriptor.version,
              input_id,
              reason,
            )
          HandlerFailed(reason) ->
            InputFailed(descriptor.kind, descriptor.version, input_id, reason)
        }
      })
  }
}

